{
  "type_map": {},
  "constraints": [
    {
      "id": "R1",
      "category": "math",
      "alternatives": [
        "df['FLOW_DURATION_MILLISECONDS'] == df['FLOW_END_MILLISECONDS'] - df['FLOW_START_MILLISECONDS']"
      ],
      "features": ["FLOW_DURATION_MILLISECONDS", "FLOW_END_MILLISECONDS", "FLOW_START_MILLISECONDS"],
      "rationale": "Duration is the difference between end and start timestamps."
    },
    {
      "id": "R2",
      "category": "math",
      "alternatives": [
        "(df['DURATION_IN'] == 0) | (np.isclose(df['SRC_TO_DST_SECOND_BYTES'], df['IN_BYTES'] * 1000 / df['DURATION_IN'], rtol=1e-3, atol=1e-3))"
      ],
      "features": ["SRC_TO_DST_SECOND_BYTES", "IN_BYTES", "DURATION_IN"],
      "rationale": "Bytes per second equals incoming bytes divided by duration in seconds (milliseconds converted to seconds)."
    },
    {
      "id": "R3",
      "category": "math",
      "alternatives": [
        "(df['DURATION_OUT'] == 0) | (np.isclose(df['DST_TO_SRC_SECOND_BYTES'], df['OUT_BYTES'] * 1000 / df['DURATION_OUT'], rtol=1e-3, atol=1e-3))"
      ],
      "features": ["DST_TO_SRC_SECOND_BYTES", "OUT_BYTES", "DURATION_OUT"],
      "rationale": "Bytes per second equals outgoing bytes divided by duration in seconds."
    },
    {
      "id": "R4a",
      "category": "math",
      "alternatives": [
        "np.isclose(df['SRC_TO_DST_AVG_THROUGHPUT'], df['SRC_TO_DST_SECOND_BYTES'] * 8, rtol=1e-3, atol=1e-3)",
        "(df['FLOW_DURATION_MILLISECONDS'] == 0) | (np.isclose(df['SRC_TO_DST_AVG_THROUGHPUT'], df['IN_BYTES'] * 8000 / df['FLOW_DURATION_MILLISECONDS'], rtol=1e-3, atol=1e-3))"
      ],
      "features": ["SRC_TO_DST_AVG_THROUGHPUT", "SRC_TO_DST_SECOND_BYTES", "IN_BYTES", "FLOW_DURATION_MILLISECONDS"],
      "rationale": "Average throughput in bits per second can be derived from bytes per second or from total bytes over flow duration."
    },
    {
      "id": "R4b",
      "category": "math",
      "alternatives": [
        "np.isclose(df['DST_TO_SRC_AVG_THROUGHPUT'], df['DST_TO_SRC_SECOND_BYTES'] * 8, rtol=1e-3, atol=1e-3)",
        "(df['FLOW_DURATION_MILLISECONDS'] == 0) | (np.isclose(df['DST_TO_SRC_AVG_THROUGHPUT'], df['OUT_BYTES'] * 8000 / df['FLOW_DURATION_MILLISECONDS'], rtol=1e-3, atol=1e-3))"
      ],
      "features": ["DST_TO_SRC_AVG_THROUGHPUT", "DST_TO_SRC_SECOND_BYTES", "OUT_BYTES", "FLOW_DURATION_MILLISECONDS"],
      "rationale": "Dst to src average throughput derivation mirror of src to dst."
    },
    {
      "id": "R5",
      "category": "math",
      "alternatives": [
        "(df['NUM_PKTS_UP_TO_128_BYTES'] + df['NUM_PKTS_128_TO_256_BYTES'] + df['NUM_PKTS_256_TO_512_BYTES'] + df['NUM_PKTS_512_TO_1024_BYTES'] + df['NUM_PKTS_1024_TO_1514_BYTES']) == (df['IN_PKTS'] + df['OUT_PKTS'])",
        "(df['NUM_PKTS_UP_TO_128_BYTES'] + df['NUM_PKTS_128_TO_256_BYTES'] + df['NUM_PKTS_256_TO_512_BYTES'] + df['NUM_PKTS_512_TO_1024_BYTES'] + df['NUM_PKTS_1024_TO_1514_BYTES']) <= (df['IN_PKTS'] + df['OUT_PKTS'])"
      ],
      "features": ["NUM_PKTS_UP_TO_128_BYTES", "NUM_PKTS_128_TO_256_BYTES", "NUM_PKTS_256_TO_512_BYTES", "NUM_PKTS_512_TO_1024_BYTES", "NUM_PKTS_1024_TO_1514_BYTES", "IN_PKTS", "OUT_PKTS"],
      "rationale": "Packet size counts should sum to total packets if no packets outside ranges, otherwise sum is a lower bound."
    },
    {
      "id": "R6",
      "category": "math",
      "alternatives": [
        "df['MIN_IP_PKT_LEN'] <= df['MAX_IP_PKT_LEN']"
      ],
      "features": ["MIN_IP_PKT_LEN", "MAX_IP_PKT_LEN"],
      "rationale": "Minimum packet length cannot exceed maximum."
    },
    {
      "id": "R7",
      "category": "math",
      "alternatives": [
        "df['MIN_TTL'] <= df['MAX_TTL']"
      ],
      "features": ["MIN_TTL", "MAX_TTL"],
      "rationale": "Minimum TTL cannot exceed maximum."
    },
    {
      "id": "R8",
      "category": "math",
      "alternatives": [
        "df['SHORTEST_FLOW_PKT'] <= df['LONGEST_FLOW_PKT']"
      ],
      "features": ["SHORTEST_FLOW_PKT", "LONGEST_FLOW_PKT"],
      "rationale": "Shortest packet length cannot exceed longest."
    },
    {
      "id": "R9",
      "category": "math",
      "alternatives": [
        "(df['SHORTEST_FLOW_PKT'] == df['MIN_IP_PKT_LEN']) & (df['LONGEST_FLOW_PKT'] == df['MAX_IP_PKT_LEN'])"
      ],
      "features": ["SHORTEST_FLOW_PKT", "LONGEST_FLOW_PKT", "MIN_IP_PKT_LEN", "MAX_IP_PKT_LEN"],
      "rationale": "Shortest/longest packet may be the same as min/max IP packet length."
    },
    {
      "id": "R10",
      "category": "math",
      "alternatives": [
        "(df['ICMP_TYPE'] // 256 == df['ICMP_IPV4_TYPE']) & ((df['ICMP_TYPE'] - df['ICMP_IPV4_TYPE'] * 256) >= 0) & ((df['ICMP_TYPE'] - df['ICMP_IPV4_TYPE'] * 256) <= 255)"
      ],
      "features": ["ICMP_TYPE", "ICMP_IPV4_TYPE"],
      "rationale": "ICMP_TYPE encodes type*256+code, so type is integer division by 256 and code is remainder."
    },
    {
      "id": "R11",
      "category": "math",
      "alternatives": [
        "df['TCP_FLAGS'] == np.bitwise_or(df['CLIENT_TCP_FLAGS'], df['SERVER_TCP_FLAGS'])"
      ],
      "features": ["TCP_FLAGS", "CLIENT_TCP_FLAGS", "SERVER_TCP_FLAGS"],
      "rationale": "Cumulative TCP flags should be the bitwise union of client and server flags."
    },
    {
      "id": "R12",
      "category": "math",
      "alternatives": [
        "(df['RETRANSMITTED_IN_BYTES'] <= df['IN_BYTES']) & (df['RETRANSMITTED_IN_PKTS'] <= df['IN_PKTS']) & (df['RETRANSMITTED_OUT_BYTES'] <= df['OUT_BYTES']) & (df['RETRANSMITTED_OUT_PKTS'] <= df['OUT_PKTS'])"
      ],
      "features": ["RETRANSMITTED_IN_BYTES", "RETRANSMITTED_IN_PKTS", "RETRANSMITTED_OUT_BYTES", "RETRANSMITTED_OUT_PKTS", "IN_BYTES", "IN_PKTS", "OUT_BYTES", "OUT_PKTS"],
      "rationale": "Retransmitted bytes/packets cannot exceed total bytes/packets in the direction."
    },
    {
      "id": "R13a",
      "category": "math",
      "alternatives": [
        "(df['SRC_TO_DST_IAT_MIN'] <= df['SRC_TO_DST_IAT_AVG']) & (df['SRC_TO_DST_IAT_AVG'] <= df['SRC_TO_DST_IAT_MAX'])"
      ],
      "features": ["SRC_TO_DST_IAT_MIN", "SRC_TO_DST_IAT_AVG", "SRC_TO_DST_IAT_MAX"],
      "rationale": "Average lies between min and max for src to dst IAT."
    },
    {
      "id": "R13b",
      "category": "math",
      "alternatives": [
        "(df['DST_TO_SRC_IAT_MIN'] <= df['DST_TO_SRC_IAT_AVG']) & (df['DST_TO_SRC_IAT_AVG'] <= df['DST_TO_SRC_IAT_MAX'])"
      ],
      "features": ["DST_TO_SRC_IAT_MIN", "DST_TO_SRC_IAT_AVG", "DST_TO_SRC_IAT_MAX"],
      "rationale": "Average lies between min and max for dst to src IAT."
    },
    {
      "id": "R14",
      "category": "math",
      "alternatives": [
        "(df['DURATION_IN'] <= df['FLOW_DURATION_MILLISECONDS']) & (df['DURATION_OUT'] <= df['FLOW_DURATION_MILLISECONDS'])"
      ],
      "features": ["DURATION_IN", "DURATION_OUT", "FLOW_DURATION_MILLISECONDS"],
      "rationale": "Directional durations cannot exceed total flow duration."
    }
  ]
}
